---
npm/caliper-docgen-storybook: patch
npm/caliper-docgen-vite-plugin: patch
---

A Storybook addon that cannot start (the native binding failed to load, or the session failed to index) now warns once, at a level Storybook shows, instead of logging at debug level, and starts again on the next request instead of caching the failure for the worker's lifetime. `fallback` and `semanticTypes` in the addon and `logLevel` in the Vite plugin fail at startup when they are not one of their choices; a typo used to log everything or act as `fallback: 'never'`. The Vite plugin reports an update it could not apply through the plugin context (`this.warn` in dev, and a failed rebuild under `vite build --watch`) instead of logging and carrying on with stale docs.
import type { CaliperStorybookOptions } from './index.js'

const FALLBACKS = ['degraded', 'never'] as const
const SEMANTIC_TYPES = ['off', 'on-demand'] as const

function assertOneOf(name: string, value: unknown, choices: readonly string[]): void {
  if (value === undefined || choices.includes(value as string)) return
  throw new Error(
    `[caliper-docgen] ${name} is '${String(value)}', expected ${choices.map((choice) => `'${choice}'`).join(' or ')}`,
  )
}

/** Throws for an option value that is not one of its choices: a typo must not silently take another meaning. */
export function assertValidOptions(options: CaliperStorybookOptions): void {
  assertOneOf('fallback', options.fallback, FALLBACKS)
  assertOneOf('semanticTypes', options.semanticTypes, SEMANTIC_TYPES)
}
import type { CaliperDocgenOptions } from './options.js'

const LOG_LEVELS = ['silent', 'error', 'warn', 'info'] as const

/** Throws for an option value that is not one of its choices: a typo must not silently take another meaning. */
export function assertValidOptions(options: CaliperDocgenOptions): void {
  const { logLevel } = options
  if (logLevel !== undefined && !LOG_LEVELS.includes(logLevel)) {
    throw new Error(
      `[caliper-docgen] logLevel is '${String(logLevel)}', expected ${LOG_LEVELS.map((level) => `'${level}'`).join(', ')}`,
    )
  }
}
